const SUMMARY_PATH = "/home/user/airdrop_summary.json";
const API_URL = "https://staging.crossmint.com/api/2022-06-09/collections/default/nfts";

async function loadRecipients() {
  const raw = await fs.readFile(RECIPIENTS_PATH, "utf8");
  const parsed = JSON.parse(raw);
  if (!Array.isArray(parsed)) {
    throw new Error("recipients.json must contain an array of email strings");
  }
  return parsed;
}

async function mintToRecipient(email, apiKey) {
  const recipient = `email:${email}:polygon-amoy`;
  const payload = {
    recipient,
    metadata: {
      name: "Welcome NFT",
      description: "Airdrop token",
      image: "https://example.com/welcome.png",
    },
  };

  const response = await fetch(API_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-api-key": apiKey,
    },
    body: JSON.stringify(payload),
  });

  const bodyText = await response.text();
  const status = response.status === 200 || response.status === 202 ? "sent" : "error";

  return {
    status,
    responseBody: bodyText,
  };
}

async function main() {
  const apiKey = process.env.CROSSMINT_API_KEY;
  if (!apiKey) {
    throw new Error("CROSSMINT_API_KEY environment variable is required");
  }

  const recipients = await loadRecipients();
  const results = [];

  for (const email of recipients) {
    try {
      const { status, responseBody } = await mintToRecipient(email, apiKey);
      const entry = { email, status };
      if (status !== "sent") {
        entry.response = responseBody;
      }
      results.push(entry);
    } catch (error) {
      results.push({
        email,
        status: "error",
        response: error instanceof Error ? error.message : String(error),
      });
    }
  }

  const summary = {
    total: recipients.length,
    results,
  };

  await fs.writeFile(SUMMARY_PATH, JSON.stringify(summary, null, 2));
}

